<?php $case=$case??[];$ownerUrl=$this->url('/mentor/profile?id='.$experience['mentor_id'].'&experience_id='.$experience['id']);$sections=[];foreach(\Morshed\Product\ExperienceCases::NARRATIVE as $key=>$label){if(trim($case[$key]??'')!==''){$sections[$key]=$label;}}$words=preg_match_all('/\S+/u',($case?implode(' ',array_map(fn($k)=>(string)($case[$k]??''),['summary',...array_keys($sections)])):$experience['body']));$minutes=max(1,(int)ceil($words/180)); ?>
<a class="reading-back" href="<?= $this->h($this->url('/experiences')) ?>"><?= $this->icon('arrow') ?>بازگشت به تجربه‌ها</a>
<article class="experience-reading"><header class="reading-hero"><div class="reading-kicker"><span><?= $this->icon('book') ?>روایت یک تجربهٔ عملی</span><span><?= $minutes ?> دقیقه مطالعه <span aria-hidden="true">·</span> نسخه <?= $this->h($experience['version_no']) ?></span></div><h1><?= $this->h($experience['title']) ?></h1><a class="reading-author" href="<?= $this->h($ownerUrl) ?>"><span class="reading-author-icon"><?= $this->icon('user') ?></span><span><small>صاحب تجربه</small><strong><?= $this->h($experience['display_name']) ?></strong></span><?= $this->icon('arrow') ?></a><?php if(!empty($case['summary'])): ?><div class="reading-lead reading-copy"><?= $this->paragraphs($case['summary']) ?></div><?php endif; ?></header>
<div class="reading-layout"><div class="reading-main"><?php if(!$case): ?><section class="reading-section reading-copy"><?= $this->paragraphs($experience['body']) ?></section><?php else: ?>
<?php $facts=['activity_area'=>'حوزهٔ فعالیت','period'=>'زمان اجرا','setting'=>'محل و بستر اجرا'];if(array_filter(array_intersect_key($case,$facts))): ?><section class="reading-facts" aria-label="شناسنامهٔ تجربه"><?php foreach($facts as $key=>$label): if(!empty($case[$key])): ?><div><span><?= $label ?></span><div class="reading-copy"><?= $this->paragraphs($case[$key]) ?></div></div><?php endif; endforeach; ?></section><?php endif; ?>
<?php $audience=['problem_statement'=>'مسئلهٔ مخاطب','target_audience'=>'گروه هدف','scale'=>'مقیاس اجرا','applicability'=>'شرایط کاربرد','constraints'=>'محدودیت‌ها'];if(array_filter(array_intersect_key($case,$audience))): ?><section class="reading-section reading-audience" id="reading-audience"><div class="reading-section-heading"><span><?= $this->icon('topic') ?></span><h2>این تجربه به کار چه کسی می‌آید؟</h2></div><?php foreach($audience as $key=>$label): if(!empty($case[$key])): ?><div class="reading-audience-item"><h3><?= $label ?></h3><div class="reading-copy"><?= $this->paragraphs($case[$key]) ?></div></div><?php endif; endforeach; ?></section><?php endif; ?>
<?php $n=0;foreach($sections as $key=>$label): $n++; ?><section class="reading-section <?= in_array($key,['results','lessons'],true)?'reading-highlight':'' ?>" id="reading-<?= $key ?>"><div class="reading-section-heading"><span><?= str_pad((string)$n,2,'0',STR_PAD_LEFT) ?></span><h2><?= $label ?></h2></div><div class="reading-copy"><?= $this->paragraphs($case[$key]) ?></div></section><?php endforeach; ?><?php endif; ?>
<?php if($assets): ?><section class="reading-section" id="reading-evidence"><div class="reading-section-heading"><span><?= $this->icon('book') ?></span><h2>مستندات این تجربه</h2></div><div class="reading-evidence"><?php foreach($assets as $asset): ?><figure><?php if(in_array($asset['media_type'],['image/png','image/jpeg'],true)): ?><img class="evidence-image" loading="lazy" src="<?= $this->h($this->url('/content/asset?id='.$asset['id'])) ?>" alt="<?= $this->h($asset['display_name']) ?>"><?php endif; ?><figcaption><a class="secondary" href="<?= $this->h($this->url('/content/asset?id='.$asset['id'])) ?>"><?= $this->h($asset['display_name']) ?></a></figcaption></figure><?php endforeach; ?></div></section><?php endif; ?>
<section class="reading-conversation"><span class="service-icon"><?= $this->icon('chat') ?></span><h2>این روایت، می‌تواند آغاز یک گفت‌وگو باشد</h2><p>برای شناخت جزئیات این مسیر، با صاحب تجربه آشنا شو.</p><a class="primary" href="<?= $this->h($ownerUrl) ?>">گفت‌وگو دربارهٔ این تجربه <?= $this->icon('arrow') ?></a><?php if(!empty($case['consultation_topics'])): ?><details><summary>موضوعات قابل گفت‌وگو</summary><div class="reading-copy"><?= $this->paragraphs($case['consultation_topics']) ?></div></details><?php endif; ?><small>مشاوره رایگان است؛ رزرو عمومی فعلاً بسته است.</small></section></div>
<aside class="reading-sidebar"><?php if($sections): ?><nav class="reading-toc" aria-label="فهرست بخش‌های تجربه"><h2>در این تجربه می‌خوانید</h2><div><?php foreach($sections as $key=>$label): ?><a href="#reading-<?= $key ?>"><?= $label ?></a><?php endforeach; ?></div></nav><?php endif; ?><section class="reading-side-owner"><span class="eyebrow">با صاحب این تجربه آشنا شو</span><h2><?= $this->h($experience['display_name']) ?></h2><?php if(!empty($case['role'])): ?><div class="reading-copy"><?= $this->paragraphs($case['role']) ?></div><?php endif; ?><a class="primary full" href="<?= $this->h($ownerUrl) ?>"><?= $this->icon('chat') ?>شناخت مرشد و گفت‌وگو</a><p class="small muted">مشاوره رایگان · رزرو عمومی فعلاً بسته است</p></section><?php if(!empty($case['outcome'])): ?><p class="reading-outcome">نتیجهٔ روایت: <strong><?= $this->h(['success'=>'موفق','failure'=>'ناموفق','mixed'=>'ترکیبی','unknown'=>'نامشخص'][$case['outcome']]) ?></strong></p><?php endif; ?></aside></div></article>
<?php if(!empty($related)): ?><section class="section"><div class="results-heading"><h2>تجربه‌های دیگری برای خواندن</h2><a href="<?= $this->h($this->url('/experiences')) ?>">همهٔ تجربه‌ها</a></div><div class="discovery-grid"><?php foreach($related as $item): ?><article class="discovery-card discovery-experience"><span class="discovery-symbol"><?= $this->icon('book') ?></span><h2><?= $this->h($item['title']) ?></h2><p class="discovery-byline"><?= $this->h($item['display_name']) ?></p><a class="discovery-card-action" href="<?= $this->h($this->url('/experience?id='.$item['id'])) ?>">خواندن تجربه <?= $this->icon('arrow') ?></a></article><?php endforeach; ?></div></section><?php endif; ?>
